"""Generated by the QA agent for STORY-105: Manage beneficiaries safely."""
from playwright.sync_api import expect


def add_ui(page, nickname, iban):
    page.get_by_test_id("nav-beneficiaries").click()
    page.get_by_test_id("beneficiary-nickname-input").fill(nickname)
    page.get_by_test_id("beneficiary-iban-input").fill(iban)
    page.get_by_test_id("beneficiary-submit").click()


def test_tc_105_01_add_valid_beneficiary_ui(signed_in):
    """TC-105-01 (UI)"""
    add_ui(signed_in, "Laila Mostafa", "EG38 0019 0005 0000 0000 2631 8099 9")
    expect(signed_in.get_by_test_id("beneficiary-success")).to_contain_text("Laila Mostafa")
    expect(signed_in.get_by_test_id("beneficiary-nickname").filter(has_text="Laila Mostafa")).to_have_count(1)


def test_tc_105_02_invalid_ibans_refused_api(amira):
    """TC-105-02 (API)"""
    bad = ["EG123", "EG3800190005000000002631800020000", "EG38001900050000000026318000A", "DE89370400440532013000"]
    for iban in bad:
        r = amira.post("/api/beneficiaries", json={"nickname": "Test", "iban": iban})
        assert r.status_code == 422, f"IBAN {iban!r} should be refused, got {r.status_code}: {r.text}"
    assert len(amira.get("/api/beneficiaries").json()) == 1


def test_tc_105_03_empty_nickname_refused_api(amira):
    """TC-105-03 (API)"""
    r = amira.post("/api/beneficiaries", json={"nickname": "  ", "iban": "EG380019000500000000263180999"})
    assert r.status_code == 422, r.text


def test_tc_105_04_nickname_shown_as_plain_text_ui(signed_in):
    """TC-105-04 (UI, security)"""
    nickname = "<b>Laila</b> <img src=x onerror=window.__xss=1>"
    add_ui(signed_in, nickname, "EG380019000500000000263180999")
    cell = signed_in.get_by_test_id("beneficiary-nickname").last
    assert cell.locator("b, img").count() == 0, "nickname HTML was rendered as markup (stored XSS)"
    assert cell.inner_text() == nickname
    assert signed_in.evaluate("window.__xss === undefined"), "script in the nickname was executed"
